Section FWA.
  Variables (SP SPA : Z) (gp tp : word) (F : bvmap 5 word) (fc : bv 32) (RNG : footprint).
  Variables (m0 : amem) (WK DT SY tl : Z) (rank : list Z) (syms : list (option Z)) (js jt : list byte) (ncells : nat).
  Variable Q : machine_state -> Prop.
  Hypothesis HTL : 1 <= tl <= 12.
  Hypothesis LR : zlen rank = 13.
  Hypothesis RR : Forall (fun v => 0 <= v <= 256) rank.
  Hypothesis HJT : length jt = (2 * ncells)%nat.
  Hypothesis HJS : length js = length syms.
  Hypothesis LSY : length syms = 256%nat.
  Hypothesis HSYR : forall i v, nth i syms None = Some v -> 0 <= v < 256.
  Hypothesis PLC : x1placeA RNG m0 SPA DT SY js ncells.
  Hypothesis HWK : ablk WK (WK + 52).
  Hypothesis DWK : WK + 52 <= DT + 4 \/ DT + 4 + 2 * Z.of_nat ncells <= WK.
  Hypothesis WSP : WK + 52 <= SPA.
  Hypothesis ZRK : zshadow m0 WK 52.
  Hypothesis RRK : rng RNG WK 52.
  Hypothesis RRKs : rng RNG (shad WK) (nshad (52 + WK mod 8)).
  Hypothesis RKA0 : u32arr asegs m0 WK (map (Z_to_bv 64) rank).
  Hypothesis FP8 : rw_cells asegs m0 (SPA + 8) (x1ptrA DT).
  Hypothesis FP64 : rw_cells asegs m0 (SPA + 64) [C8 (Z_to_bv 64 (DT + 12)); C8 (Z_to_bv 64 (DT + 4))].
  Hypothesis FP104 : rw_cells asegs m0 (SPA + 104) [C8 (Z_to_bv 64 (tl + 1)); C8 (Z_to_bv 64 (tl + 1))].
  Hypothesis FP120 : rw_cells asegs m0 (SPA + 120) [C8 (Z_to_bv 64 DT)].
  Hypothesis FP128 : rw_cells asegs m0 (SPA + 128) [C8 (Z_to_bv 64 WK)].
  Notation INV m1 cells := (x1fA_inv m0 m1 SPA DT SY js jt syms ncells cells).

  Lemma fwA_loop : forall f w cells u sym m1 (j136 j144 j160 j184 j192 j208 : list byte)
      (x1 x5 x6 x10 x11 x12 x15 x16 x17 x18 x19 x21 x22 x23 x24 x25 x26 x27 x28 x29 x30 x31 : word) r,
    fill_weights f w tl rank syms cells sym u = Ok r -> Z.of_nat f = tl + 1 - w -> 1 <= w <= tl ->
    0 <= sym <= 256 -> 0 <= u <= Z.of_nat ncells ->
    INV m1 cells -> rw_cells asegs m1 (SPA + 136) (x1frI u sym SY j136 j144 j160 j184 j192 j208) ->
    (forall m2 u' sym' wp' cp' (j144' j160' j192' j208' : list byte)
            (y1 y5 y6 y7 y10 y11 y12 y13 y14 y15 y16 y17 y18 y19 y21 y22 y23 y24 y25 y26 y27 y28 y29 y30 y31 : word),
       INV m2 r -> rw_cells asegs m2 (SPA + 136) (x1frA wp' u' sym' cp' SY j144' j160' j192' j208') ->
       evtF asegs RNG Q
         (MS (mkR y1 (Z_to_bv 64 SPA) gp tp y5 y6 y7 (Z_to_bv 64 SP) (Z_to_bv 64 SPA) y10 y11 y12 y13 y14 y15 y16 y17 y18 y19
                  (Z_to_bv 64 2147450880) y21 y22 y23 y24 y25 y26 y27 y28 y29 y30 y31)
             F (Z_to_bv 64 0x8124c) fc None m2 (seg_rom asegs))) ->
    evtF asegs RNG Q
      (MS (mkR x1 (Z_to_bv 64 SPA) gp tp x5 x6 (Z_to_bv 64 WK) (Z_to_bv 64 SP) (Z_to_bv 64 SPA) x10 x11 x12 (Z_to_bv 64 1)
               (Z_to_bv 64 w) x15 x16 x17 x18 x19 (Z_to_bv 64 2147450880) x21 x22 x23 x24 x25 x26 x27 x28 x29 x30 x31)
          F (Z_to_bv 64 0x80a54) fc None m1 (seg_rom asegs)).
Proof using HTL LR RR HJT HJS LSY HSYR PLC HWK DWK WSP ZRK RRK RRKs RKA0 FP8 FP64 FP104 FP120 FP128.
